from playwright.sync_api import sync_playwright
from datetime import datetime,timezone
import json
URL='http://127.0.0.1:8001'
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox'])
 for zone in ['UTC','Asia/Seoul','America/Los_Angeles']:
  c=b.new_context(viewport={'width':390,'height':844},timezone_id=zone);pg=c.new_page();pg.clock.set_fixed_time(datetime(2026,10,25,15,30,tzinfo=timezone.utc));pg.goto(URL+'/v3/?day=213',wait_until='domcontentloaded');pg.wait_for_function('window.PlannerCore');pg.evaluate('''async()=>{await PlannerCore.load();await PlannerCore.settings({babyName:'날짜 QA',birthday:'2026-03-26',startDay:180,stage:'middle',mealsPerDay:2});}''');pg.reload(wait_until='domcontentloaded');assert pg.evaluate('PlannerCore.todayISO()')=='2026-10-26';pg.locator('[data-action=today]').click();assert '생후 215일' in pg.locator('#profileLine').inner_text();pg.locator('#legacyLink').click();pg.wait_for_url('**/?day=215');pg.locator('#todayBtn').click();assert '생후 215일' in pg.locator('#babyProfileSummary').inner_text();pg.locator('#openJump').click();pg.locator('#jumpDate').fill('2026-10-24');pg.locator('#jumpDateBtn').click();assert '생후 213일' in pg.locator('#babyProfileSummary').inner_text();assert '215일' not in pg.locator('#status').inner_text();print('PASS Korean midnight, today and selected date in',zone);c.close()
 # Read pre-existing localStorage without creating a replacement schema or migration.
 fixture={'babyName':'기존 아기','birthday':'2026-03-26','startDay':180,'days':{'180':{'foods':[{'name':'당근','g':20,'icon':'🥕'}],'actualIntake':15,'allergy':True,'added':'기존 추가','memo':'날짜 메모'}},'cubes':[{'id':'archived-batch','name':'당근','grams':10,'initialQty':3,'remainingQty':2,'madeOn':'2026-09-01','storage':'frozen','cabinetRemovedAt':'2026-09-02T00:00:00Z'}],'cubeUsages':[{'id':'usage-old','cubeBatchId':'archived-batch','foodName':'당근','cubeGrams':10,'quantity':1,'mealDay':180,'status':'used'}],'ingredients':[{'id':'original-id','name':'당근','preference':'like','allergy':'suspected','firstTriedDay':180,'firstTriedOn':'2026-09-21','memo':'재료 메모'}],'preferences':{},'v3Settings':{'stage':'middle','mealsPerDay':2}}
 c=b.new_context(viewport={'width':390,'height':844});c.add_init_script('if(!localStorage.getItem("main"))localStorage.setItem("main",'+json.dumps(json.dumps(fixture,ensure_ascii=False))+');');pg=c.new_page();pg.goto(URL+'/v3/?day=180',wait_until='domcontentloaded');pg.wait_for_function('window.PlannerCore');pg.wait_for_selector('[data-meal]');assert pg.evaluate('JSON.parse(localStorage.main)')==fixture
 pg.locator('#legacyLink').click();pg.wait_for_url('**/?day=180');assert '기존 아기' in pg.locator('#babyProfileSummary').inner_text();assert '15g' in pg.locator('#weekDetail').inner_text();assert '날짜 메모' in pg.locator('#weekDetail').inner_text();assert pg.evaluate('JSON.parse(localStorage.main)')==fixture
 pg.locator('#v3Switch').click();pg.wait_for_url('**/v3/?day=180');result=pg.evaluate('''async()=>{const C=PlannerCore;await C.load();const before=JSON.parse(C.backup()).state;await C.restore(JSON.parse(C.backup()),'full');const after=JSON.parse(C.backup()).state;delete before.updatedAt;delete after.updatedAt;if(JSON.stringify(before)!==JSON.stringify(after))throw Error('backup mismatch');return after;}''');assert result['days']['180']['actualIntake']==15;assert result['days']['180']['allergy'] is True;assert result['cubes'][0]['cabinetRemovedAt'];assert result['ingredients'][0]['id']=='original-id';assert result['cubeUsages'][0]['quantity']==1
 print('PASS existing localStorage load, V1/V3 compatibility, profile/intake/memos/allergy/introduction/deleted cube/usage and backup restore');b.close()
